@FunctionalInterface
public interface PricingStrategy {
    BigDecimal calculatePrice(BigDecimal basePrice);

    default PricingStrategy andThen(PricingStrategy after) {
        return (BigDecimal price) -> after.calculatePrice(this.calculatePrice(price));
    }
}

public class OrderService {
    public BigDecimal processOrder(BigDecimal basePrice, PricingStrategy strategy) {
        // Higher-order function accepting a strategy behavior
        return strategy.calculatePrice(basePrice);
    }

    public static void main(String[] args) {
        OrderService service = new OrderService();
        PricingStrategy vipDiscount = price -> price.multiply(BigDecimal.valueOf(0.80));
        PricingStrategy taxAddition = price -> price.multiply(BigDecimal.valueOf(1.08));

        // Composing strategies dynamically
        PricingStrategy finalStrategy = vipDiscount.andThen(taxAddition);
        BigDecimal finalAmount = service.processOrder(BigDecimal.valueOf(100.00), finalStrategy);
    }
}
